import{c as s,Q as e,j as t,m as n}from"./chunks/framework.DOi4mjdC.js";const l="/assets/%E6%9C%AA%E5%BC%80%E5%90%AFPartial-Output%E5%8A%9F%E8%83%BD%E8%AE%A1%E7%AE%97%E7%A4%BA%E6%84%8F%E5%9B%BE.Bo0vaMVn.png",p="/assets/%E5%BC%80%E5%90%AFPartial-Output%E5%8A%9F%E8%83%BD%E8%AE%A1%E7%AE%97%E7%A4%BA%E6%84%8F%E5%9B%BE.lLf4Q7Vj.png",h=JSON.parse('{"title":"单次矩阵乘局部输出","description":"","frontmatter":{},"headers":[{"level":1,"title":"单次矩阵乘局部输出","slug":"单次矩阵乘局部输出"},{"level":2,"title":"功能介绍","slug":"功能介绍"},{"level":2,"title":"使用场景","slug":"使用场景"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/单次矩阵乘局部输出.md","filePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/单次矩阵乘局部输出.md"}'),r={name:"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/单次矩阵乘局部输出.md"};function i(o,a,c,u,m,d){return e(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="单次矩阵乘局部输出" tabindex="-1">单次矩阵乘局部输出 <a class="header-anchor" href="#单次矩阵乘局部输出" aria-label="Permalink to &quot;单次矩阵乘局部输出&quot;">​</a></h1><h2 id="功能介绍" tabindex="-1">功能介绍 <a class="header-anchor" href="#功能介绍" aria-label="Permalink to &quot;功能介绍&quot;">​</a></h2><p>单次矩阵乘局部输出，又称Partial Output。如<a href="./../基础知识.html#zh-cn_topic_0000001622194138_li123441825184114">基础知识</a>中所述，一次Iterate计算过程中，会按K方向进行一次或多次基本块计算，其中的一次基本块计算为baseM*baseK和baseK*baseN大小的输入数据进行计算得到baseM*baseN大小的结果；每次基本块计算的结果进行累加后，便得到baseM*singleCoreK和singleCoreK*baseN大小的输入数据计算得到的结果baseM*baseN，并将其作为一次Iterate的最终结果输出。</p><p>开启Partial Output功能后，调用Iterate接口不会进行K轴累加，只进行单次基本块计算。用户可以通过GetTensorC接口获取对应的单片数据，最后自行进行K轴上的累加。</p><p><strong>图 1</strong> 未开启Partial Output功能计算示意图<br><img src="'+l+'" alt="" title="未开启Partial-Output功能计算示意图"></p><p><strong>图 2</strong> 开启Partial Output功能计算示意图<br><img src="'+p+`" alt="" title="开启Partial-Output功能计算示意图"></p><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to &quot;使用场景&quot;">​</a></h2><p>矩阵乘计算结果不需要累加，只需要输出baseM*baseK和baseK*baseN的计算结果baseM*baseN。例如需要先获取单次基本块计算的数据进行反量化，再累加得到最终结果。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>该功能仅支持<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/MatmulConfig.md" target="_blank" rel="noreferrer">MDL模板</a>。</li><li>获取矩阵乘计算结果时，仅支持调用Iterate和GetTensorC接口的连续写模式，不支持非连续写模式以及IterateAll接口获取计算结果，连续写模式的介绍请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/GetTensorC.md" target="_blank" rel="noreferrer">GetTensorC</a>。</li><li>该功能不支持带有Bias矩阵的Matmul计算，即不支持输入Bias矩阵。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>完整的算子样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul_partial_output" target="_blank" rel="noreferrer">开启Partial Output功能的算子样例</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 配置MDL模板，使能Partial Output</span></span>
<span class="line"><span>constexpr static MatmulConfigMode configMode = MatmulConfigMode::CONFIG_MDL;</span></span>
<span class="line"><span>constexpr static MatmulFuncParams funcParams = {</span></span>
<span class="line"><span>  false, false, false, false, 0, IterateOrder::UNDEF, ScheduleType::INNER_PRODUCT, true, true,</span></span>
<span class="line"><span>  true /* isPartialOutput */</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>constexpr static MatmulConfig CFG_PARTIAL = GetMMConfig&lt;configMode&gt;(funcParams);</span></span>
<span class="line"><span>Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, CFG_PARTIAL&gt; mm;</span></span>
<span class="line"><span>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm);</span></span>
<span class="line"><span>mm.Init(&amp;tiling);</span></span>
<span class="line"><span>mm.SetTensorA(gmA, isTransposeA);</span></span>
<span class="line"><span>mm.SetTensorB(gmB, isTransposeB);</span></span>
<span class="line"><span>while (mm.Iterate()) {</span></span>
<span class="line"><span>    mm.GetTensorC(tmpGmC[dstOffset], false, true);</span></span>
<span class="line"><span>    dstOffset += baseM * baseN;</span></span>
<span class="line"><span>    // 其他操作</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,13)])])}const b=s(r,[["render",i]]);export{h as __pageData,b as default};
